/**
 * Fast O(1) synchronous lookup with smart lemmatization, contraction resolution,
 * and morphological fallback (handling plurals, past tense, continuous, possessives).
 */
export function lookupCurriculumWord(cleanWord: string): DictionaryEntry | null {
  if (!cleanWord) return null;
  const normalized = cleanWord.trim().toLowerCase().replace(/^[^a-z0-9']+|[^a-z0-9']+$/gi, "");
  if (!normalized) return null;

  // 1. Direct O(1) dictionary match
  if (CURRICULUM_DICTIONARY[normalized]) {
    return CURRICULUM_DICTIONARY[normalized];
  }

  // 2. Strip OCR newline artifact if starts with 'n' followed by a known word
  if (normalized.startsWith("n") && normalized.length > 2 && CURRICULUM_DICTIONARY[normalized.slice(1)]) {
    return CURRICULUM_DICTIONARY[normalized.slice(1)];
  }

  // 3. Contractions normalization
  const contractionMap: Record<string, string> = {
    "im": "i'm",
    "it's": "it's",
    "its": "its",
    "whats": "what's",
    "what's": "what's",
    "whos": "who's",
    "who's": "who's",
    "wheres": "where's",
    "where's": "where's",
    "hows": "how's",
    "theres": "there's",
    "there's": "there's",
    "heres": "here's",
    "here's": "here's",
    "thats": "that's",
    "that's": "that's",
    "hes": "he's",
    "he's": "he's",
    "shes": "she's",
    "she's": "she's",
    "were": "we're",
    "we're": "we're",
    "theyre": "they're",
    "they're": "they're",
    "youre": "you're",
    "you're": "you're",
    "dont": "don't",
    "don't": "don't",
    "doesnt": "doesn't",
    "doesn't": "doesn't",
    "didnt": "didn't",
    "didn't": "didn't",
    "cant": "can't",
    "can't": "can't",
    "isnt": "isn't",
    "isn't": "isn't",
    "arent": "aren't",
    "aren't": "aren't",
    "havent": "haven't",
    "haven't": "haven't",
    "hasnt": "hasn't",
    "hasn't": "hasn't",
    "lets": "let's",
    "let's": "let's",
    "oclock": "o'clock",
    "o'clock": "o'clock"
  };

  if (contractionMap[normalized] && CURRICULUM_DICTIONARY[contractionMap[normalized]]) {
    return CURRICULUM_DICTIONARY[contractionMap[normalized]];
  }

  // 4. Possessive 's fallback (e.g. "Ahmed's", "Dalia's", "teacher's")
  if (normalized.endsWith("'s")) {
    const baseWord = normalized.slice(0, -2);
    if (CURRICULUM_DICTIONARY[baseWord]) {
      const base = CURRICULUM_DICTIONARY[baseWord];
      return {
        arabic: `خاص بـ ${base.arabic} (ملكية)`,
        definition: `Belonging to ${baseWord} (possessive form)`,
        partOfSpeech: "possessive"
      };
    }
  }

  // 5. Regular Plural -ies (e.g. "babies" -> "baby", "strawberries" -> "strawberry")
  if (normalized.endsWith("ies")) {
    const singular = normalized.slice(0, -3) + "y";
    if (CURRICULUM_DICTIONARY[singular]) {
      const base = CURRICULUM_DICTIONARY[singular];
      return {
        arabic: `جمع: ${base.arabic}`,
        definition: `Plural form of ${singular}: ${base.definition}`,
        partOfSpeech: "plural"
      };
    }
  }

  // 6. Regular Plural -es (e.g. "mangoes" -> "mango", "boxes" -> "box")
  if (normalized.endsWith("es")) {
    const singular = normalized.slice(0, -2);
    if (CURRICULUM_DICTIONARY[singular]) {
      const base = CURRICULUM_DICTIONARY[singular];
      return {
        arabic: `جمع: ${base.arabic}`,
        definition: `Plural form of ${singular}: ${base.definition}`,
        partOfSpeech: "plural"
      };
    }
  }

  // 7. Regular Plural -s (e.g. "pupils" -> "pupil", "cats" -> "cat", "bags" -> "bag")
  if (normalized.endsWith("s")) {
    const singular = normalized.slice(0, -1);
    if (CURRICULUM_DICTIONARY[singular]) {
      const base = CURRICULUM_DICTIONARY[singular];
      return {
        arabic: `جمع: ${base.arabic}`,
        definition: `Plural form of ${singular}: ${base.definition}`,
        partOfSpeech: "plural"
      };
    }
  }

  // 8. Continuous -ing (e.g. "jumping" -> "jump", "writing" -> "write")
  if (normalized.endsWith("ing")) {
    const verb1 = normalized.slice(0, -3);
    if (CURRICULUM_DICTIONARY[verb1]) {
      const base = CURRICULUM_DICTIONARY[verb1];
      return {
        arabic: `في حالة الاستمرار: ${base.arabic}`,
        definition: `Continuous (-ing) form of ${verb1}: ${base.definition}`,
        partOfSpeech: "verb"
      };
    }
    const verb2 = normalized.slice(0, -3) + "e";
    if (CURRICULUM_DICTIONARY[verb2]) {
      const base = CURRICULUM_DICTIONARY[verb2];
      return {
        arabic: `في حالة الاستمرار: ${base.arabic}`,
        definition: `Continuous (-ing) form of ${verb2}: ${base.definition}`,
        partOfSpeech: "verb"
      };
    }
  }

  // 9. Past tense -ed (e.g. "played" -> "play", "liked" -> "like")
  if (normalized.endsWith("ed")) {
    const verb1 = normalized.slice(0, -2);
    if (CURRICULUM_DICTIONARY[verb1]) {
      const base = CURRICULUM_DICTIONARY[verb1];
      return {
        arabic: `في الماضي: ${base.arabic}`,
        definition: `Past tense of ${verb1}: ${base.definition}`,
        partOfSpeech: "verb"
      };
    }
    const verb2 = normalized.slice(0, -1);
    if (CURRICULUM_DICTIONARY[verb2]) {
      const base = CURRICULUM_DICTIONARY[verb2];
      return {
        arabic: `في الماضي: ${base.arabic}`,
        definition: `Past tense of ${verb2}: ${base.definition}`,
        partOfSpeech: "verb"
      };
    }
  }

  return null;
}
